function markdownListToJson(md) {
  const lines = md.split('\n');
  const result = {};
  const stack = [{ obj: result, indent: -1 }];

  lines.forEach(line => {
    // 1. Clean the line and skip if empty
    if (!line.trim()) return;

    // 2. Determine indentation and content
    const indent = line.search(/\S/);
    const content = line.trim().replace(/^[\*\-\+]\s+/, ''); // Remove bullet (*, -, +)

    // 3. Split into Key and Value
    let [key, ...valParts] = content.split(':');
    key = key.replace(/\*\*/g, '').trim(); // Remove bold formatting from keys
    let value = valParts.join(':').trim();

    // 4. Determine Value Type
    if (value === 'true') value = true;
    else if (value === 'false') value = false;
    else if (value !== '' && !isNaN(value)) value = Number(value);

    // 5. Manage stack based on indentation
    while (stack.length > 1 && indent <= stack[stack.length - 1].indent) {
      stack.pop();
    }

    const currentParent = stack[stack.length - 1].obj;

    if (value === '') {
      // It's a nested object or array
      // We'll assume object for now; if we find bullets without keys later, 
      // a more complex parser would convert this to an array.
      currentParent[key] = {};
      stack.push({ obj: currentParent[key], indent: indent });
    } else {
      // It's a leaf node
      currentParent[key] = value;
    }
  });

  return result;
}

function jsonToMarkdownList(obj, indent = 0) {
  let markdown = '';
  const spacing = '  '.repeat(indent);

  for (const key in obj) {
    if (Object.prototype.hasOwnProperty.call(obj, key)) {
      const value = obj[key];

      if (value !== null && typeof value === 'object' && !Array.isArray(value)) {
        // Nested Object
        markdown += `${spacing}* **${key}**:\n${jsonToMarkdownList(value, indent + 1)}`;
      } else if (Array.isArray(value)) {
        // Array
        markdown += `${spacing}* **${key}**:\n`;
        value.forEach(item => {
          if (typeof item === 'object') {
            markdown += jsonToMarkdownList(item, indent + 1);
          } else {
            markdown += `${spacing}  * ${item}\n`;
          }
        });
      } else {
        // Primitive value
        markdown += `${spacing}* **${key}**: ${value}\n`;
      }
    }
  }
  return markdown;
}



for (const item of $input.all()) {
  if(item.json.jsonValue){
    item.json.markdownValue = jsonToMarkdownList(item.json.jsonValue)
  } else if(item.json.markdownValue){
    item.json.jsonValue = markdownListToJson(item.json.markdownValue)
  }
}

return $input.all();

